(zops_api) {
	# ZEL_TRADE_STATE_READONLY_SHIM_BEGIN
	@trade_state path /api/trade/state
	handle @trade_state {
		rewrite * /api/portfolio/state
		reverse_proxy 127.0.0.1:8000 {
			header_up Host {host}
			header_up X-Forwarded-Proto {scheme}
			header_up X-Forwarded-Host {host}
			header_down X-ZEL-Trade-State-Shim "portfolio-state-readonly"
		}
	}
	# ZEL_TRADE_STATE_READONLY_SHIM_END
	@api path /api/* /api/v1/* /docs* /openapi.json /redoc* /health*
	handle @api {
		reverse_proxy 127.0.0.1:8000 {
			header_up Host {host}
			header_up X-Forwarded-Proto {scheme}
			header_up X-Forwarded-Host {host}
		}
	}
}

(zops_headers) {
	header {
		X-ZEL-Order-Authority "blocked"
		X-ZEL-Route-Split "locked"
		Cache-Control "no-store, no-cache, must-revalidate, max-age=0"
		Pragma "no-cache"
		Expires "0"
	}
}

z-os.vip {
	encode zstd gzip
	import zops_headers
	header X-ZEL-Surface "web"
	header X-ZEL-Root "/var/www/z-os-web"
	import zops_api
	handle {
		root * /var/www/z-os-web
		try_files {path} /index.html
		file_server
	}
}

app.z-os.vip {
	encode zstd gzip
	import zops_headers
	header X-ZEL-Surface "app-latest-operational-console"
	header X-ZEL-Root "/var/www/z-os-app"
	import zops_api
	handle {
		root * /var/www/z-os-app
		try_files {path} /index.html
		file_server
	}
}


api.z-os.vip {
	reverse_proxy 127.0.0.1:8000
}

tv.z-os.vip {
	reverse_proxy 127.0.0.1:8000
}

dash.z-os.vip {
	reverse_proxy 127.0.0.1:8000
}

origin.z-os.vip {
	reverse_proxy 127.0.0.1:8000
}

# ZEL_ALIMI_MESSENGER_SOURCEBOUND_V30_20260513

# W130 authoritative alimi route - generated 2026-06-06
alimi.z-os.vip {

    # W208_PAPER_CONTROL_API_ROUTE
    handle /api/paper-control/command* {
        reverse_proxy 127.0.0.1:8792
    }

    encode gzip

    header {
        Cache-Control "no-store, no-cache, must-revalidate, max-age=0"
        X-ZEL-Alimi-Root "w130-caddy-var-www-z-os-alimi"
    }

    # Q4R3_EXACT25_VIEW_CONTRACT_ROUTE_BEGIN
    handle /api/view_contract_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /view_contract_latest.json
        header Content-Type "application/json"
        header Cache-Control "no-store, no-cache, must-revalidate"
        file_server
    }
    # Q4R3_EXACT25_VIEW_CONTRACT_ROUTE_END
    handle_path /api/* {
        root * /var/www/z-os-alimi/api
        header Content-Type "application/json"
        file_server
    }

    handle_path /static/* {
        root * /var/www/z-os-alimi/static
        file_server
