        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_evaluation_status_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_evaluation_status_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_evaluation_metrics_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_evaluation_metrics_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_performance_aggregator_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_performance_aggregator_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle /paper_30d_perf_edge_latest.json {
        root * /var/www/z-os-alimi/api
        rewrite * /paper_30d_perf_edge_latest.json
        header Content-Type "application/json"
        file_server
    }

    handle {
        root * /var/www/z-os-alimi
        try_files {path} {path}/ /index.html
        file_server
